package in.navrakshak.idr;

import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;

/** Demo operator screen for roster onboarding and auditable attendance checks. */
public final class WorkforceActivity extends Activity {
 private WorkforceDatabase db; private LinearLayout list; private EditText code,project,lat,lon,accuracy;
 public void onCreate(Bundle b){super.onCreate(b);db=new WorkforceDatabase(this); build();}
 private int d(int x){return AppUi.dp(this,x);} private EditText input(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(AppUi.TEXT);e.setHintTextColor(AppUi.MUTED);e.setSingleLine();e.setPadding(d(12),d(5),d(12),d(5));e.setBackground(AppUi.outlinedShape(this,AppUi.PANEL,12,AppUi.BORDER));return e;}
 private void build(){LinearLayout root=AppUi.page(this); LinearLayout bar=AppUi.row(this);bar.addView(AppUi.iconButton(this,R.drawable.ic_arrow_back,"Back",this::finish),new LinearLayout.LayoutParams(d(48),d(48)));bar.addView(AppUi.title(this,"Workforce control",20),AppUi.weighted(this,8));root.addView(bar);AppUi.gap(root,12);root.addView(AppUi.text(this,"Roster onboarding • attendance validation",13,AppUi.MUTED));AppUi.gap(root,14);
  root.addView(AppUi.title(this,"Onboard worker",17));AppUi.gap(root,8); EditText name=input("Full name");root.addView(name);AppUi.gap(root,7);code=input("Worker code (e.g. WK-001)");root.addView(code);AppUi.gap(root,7);EditText id=input("Government ID hash / synthetic ID");root.addView(id);AppUi.gap(root,7);EditText face=input("Face template hash (optional demo value)");root.addView(face);AppUi.gap(root,7);EditText phone=input("Phone (optional)");root.addView(phone);AppUi.gap(root,7);project=input("Assigned project code");root.addView(project);AppUi.gap(root,8);root.addView(AppUi.button(this,"Save to roster",true,()->{try{db.addWorker(code.getText().toString(),name.getText().toString(),phone.getText().toString(),id.getText().toString(),face.getText().toString(),project.getText().toString());toast("Worker onboarded");refresh();}catch(Exception e){toast("Cannot save: code must be unique and fields are required");}}));AppUi.gap(root,18);
  root.addView(AppUi.title(this,"Capture attendance",17));AppUi.gap(root,8);root.addView(AppUi.text(this,"Checks: active roster, project assignment, one entry per day and GPS accuracy.",12,AppUi.MUTED));AppUi.gap(root,8);lat=input("Latitude");lon=input("Longitude");accuracy=input("GPS accuracy in metres");LinearLayout gps=AppUi.row(this);gps.addView(lat,new LinearLayout.LayoutParams(0,d(52),1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,d(52),1);lp.setMarginStart(d(7));gps.addView(lon,lp);root.addView(gps);AppUi.gap(root,7);root.addView(accuracy);AppUi.gap(root,7);root.addView(AppUi.button(this,"Validate and record attendance",true,()->capture()));AppUi.gap(root,18);root.addView(AppUi.title(this,"Today’s audit log",17));AppUi.gap(root,8);list=AppUi.column(this);root.addView(list);setContentView(root);refresh();}
 private void capture(){try{String result=db.mark(code.getText().toString(),project.getText().toString(),Double.parseDouble(lat.getText().toString()),Double.parseDouble(lon.getText().toString()),Float.parseFloat(accuracy.getText().toString()),"demo-evidence");toast(result);refresh();}catch(Exception e){toast("Enter a roster code, project and valid GPS values");}}
 private void refresh(){if(list==null)return;list.removeAllViews();String day=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());android.database.Cursor c=db.attendance(day);try{while(c.moveToNext()){TextView row=AppUi.text(this,c.getString(0)+" • "+c.getString(1)+"\n"+c.getString(2)+" • "+c.getString(5)+" • ±"+c.getFloat(4)+"m\n"+c.getString(6),13,AppUi.TEXT);row.setPadding(d(12),d(10),d(12),d(10));row.setBackground(AppUi.outlinedShape(this,AppUi.PANEL,12,AppUi.BORDER));list.addView(row,new LinearLayout.LayoutParams(-1,d(80)));AppUi.gap(list,6);}}finally{c.close();}}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
